{
  "findings": [
    {
      "ref": "[D520]",
      "area": "age_gating",
      "claim": "A parent reports that Common Sense Media recommends YouTube Kids for kids 7 and older, while the app store says it is for 4 and older.",
      "stance": "risk",
      "quote": "The app store says YouTube Kids is for 4 and older, but Common Sense Media recommends it for kids 7 and older."
    },
    {
      "ref": "[D520]",
      "area": "content",
      "claim": "A parent reports seeing disturbing videos that use familiar characters from kids' TV shows and become strange or extremely disturbing.",
      "stance": "risk",
      "quote": "These videos may use familiar characters from kids' TV shows, such as Caillou or Peppa Pig, or they may use cartoon graphics such as cars and trucks. The videos have seemingly kid-friendly titles and begin normally, but then become strange and even extremely disturbing."
    },
    {
      "ref": "[D520]",
      "area": "content",
      "claim": "A parent reports that disturbing videos have included suicide instructions spliced into cartoon videos.",
      "stance": "risk",
      "quote": "there have been scattered cases of disturbing videos popping up in the kid's app, including a well-publicized incident of [\"suicide instructions\" spliced in a cartoon video](https://www.cnn.com/2019/02/25/tech/youtube-suicide-videos-trnd/index.html)."
    },
    {
      "ref": "[D520]",
      "area": "mitigation",
      "claim": "A parent reports that YouTube has added human monitors to review flagged content and proactively look for disturbing material.",
      "stance": "mitigation",
      "quote": "the addition of human monitors reviewing flagged content and proactively looking for disturbing content -- which Google instituted after concerns surfaced about disturbing videos making it through the algorithm -- should help a lot."
    },
    {
      "ref": "[D520]",
      "area": "mitigation",
      "claim": "A parent reports that YouTube will automatically age-restrict videos flagged on the main app, blocking them from the Kids app.",
      "stance": "mitigation",
      "quote": "when videos are flagged on the main YouTube app, they will automatically be age-restricted and therefore blocked from the Kids app."
    },
    {
      "ref": "[D520]",
      "area": "mitigation",
      "claim": "A parent reports that YouTube will remove the ability for producers of disturbing content to serve ads on age-restricted videos.",
      "stance": "mitigation",
      "quote": "by eliminating their ability to serve ads on the age-restricted content."
    },
    {
      "ref": "[D520]",
      "area": "mitigation",
      "claim": "A parent reports that users can block or report disturbing videos to prevent them from resurfacing and alert YouTube for review.",
      "stance": "mitigation",
      "quote": "If you find a disturbing video, you can block it, which makes sure the video doesn't surface again. You can also report it, which alerts YouTube of the offensive content so that their team can review and remove it if necessary."
    }
  ]
}
